<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {ElAlert,ElButton,ElEmpty,ElProgress,ElSkeleton} from 'element-plus';
import {requestClient} from '#/api/request';
const props=defineProps<{programId:string}>();
type Summary={visible:boolean;count:number;minimum:number;reason:string;average?:number;distribution?:number[]};
const data=ref<Summary|null>(null),loading=ref(false),error=ref('');
async function load(){loading.value=true;error.value='';try{data.value=await requestClient.get('/growth/programs/'+props.programId+'/feedback-summary')}catch{data.value=null;error.value='反馈汇总读取失败，请重试'}finally{loading.value=false}}
onMounted(load);
</script>
<template><section class="feedback-summary"><div class="summary-header"><div><p class="eyebrow">EXPERIENCE INSIGHTS</p><h2>参与体验回看</h2><p>用于改善活动安排，不用于心理评估或个人排名。</p></div><ElButton :loading="loading" @click="load">刷新</ElButton></div><ElAlert v-if="error" :title="error" type="error" :closable="false" show-icon/><ElSkeleton v-if="loading" :rows="5" animated/><template v-else-if="data"><ElAlert :title="data.reason" type="info" :closable="false" show-icon/><template v-if="data.visible"><div class="summary-metrics"><div><span>体验适配度</span><strong>{{data.average}}<small> / 5</small></strong></div><div><span>有效反馈</span><strong>{{data.count}}<small> 份</small></strong></div></div><h3>评分分布</h3><div v-for="(count,i) in data.distribution" :key="i" class="distribution-row"><span>{{i+1}} 分</span><ElProgress :percentage="Math.round(Number(count)/Number(data.count)*100)" :show-text="false" :stroke-width="12"/><span>{{count}} 份</span></div></template><div v-else class="protected-state"><ElEmpty :description="Number(data.count)>0?'反馈已收集，暂不展示评分':'暂无可展示的评分汇总'" :image-size="90"/><p v-if="Number(data.count)>0">{{data.count}} / {{data.minimum}} 份 · 达到展示门槛后再查看</p><p>不展示参加者姓名、单条评分或私密笔记。</p></div></template></section></template>
<style scoped>.summary-header{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:24px}.eyebrow{font-size:10px;letter-spacing:2px;color:var(--el-color-primary)}h2{font-size:23px;font-weight:650;margin:10px 0}p{font-size:13px;color:var(--el-text-color-secondary);line-height:1.8}.summary-metrics{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:24px 0}.summary-metrics>div{padding:24px;background:var(--el-color-primary-light-9);border:1px solid var(--el-border-color-light);border-radius:16px}.summary-metrics span{font-size:13px;color:var(--el-text-color-secondary)}.summary-metrics strong{display:block;font-size:34px;margin-top:12px;color:var(--el-color-primary)}.summary-metrics small{font-size:13px;font-weight:400}h3{font-size:15px;margin-bottom:20px}.distribution-row{display:grid;grid-template-columns:45px 1fr 55px;gap:16px;align-items:center;margin:18px 0;font-size:13px;color:var(--el-text-color-regular)}.protected-state{text-align:center;padding:16px}.protected-state p{margin:8px 0}@media(max-width:520px){.summary-metrics>div{padding:16px}.summary-header{align-items:flex-start}.distribution-row{gap:10px}}</style>
